mapper.sql:
WITH input_users AS ( SELECT id AS user_id FROM sys_user WHERE id IN
#{userId}
), user_subjects AS ( SELECT 'USER' AS sub_type, u.user_id AS sub_id, u.user_id AS user_id FROM input_users u UNION ALL SELECT 'DEPT' AS sub_type, dc.ancestor_id AS sub_id, ud.user_id AS user_id FROM v_user_dept_effective ud JOIN input_users u ON ud.user_id = u.user_id JOIN dept_closure dc ON ud.dept_id = dc.descendant_id JOIN sys_dept da ON da.id = dc.ancestor_id AND da.status = 1 -- 未来扩展：在此处 UNION ALL 增加 PROJECT 或其他主体即可 -- UNION ALL SELECT 'PROJECT', project_id FROM user_project ... UNION ALL SELECT 'POST' AS sub_type, up.post_id AS sub_id, up.user_id AS user_id FROM v_user_post_effective up JOIN input_users u ON up.user_id = u.user_id )
